// Independent analytic regular-polygon cylinder for native per-glyph acceptance.
import{createMesh}from'../../shared/geometry.js';
export function glyphCylinder({radius=20,height=30,sides=96,position=[0,0,0]}={}){const vertices=[],triangles=[];for(const z of[-height/2,height/2])for(let i=0;i<sides;i++){const a=2*Math.PI*i/sides;vertices.push([radius*Math.cos(a),radius*Math.sin(a),z]);}for(let i=0;i<sides;i++){const j=(i+1)%sides;triangles.push([i,j,sides+j],[i,sides+j,sides+i]);}vertices.push([0,0,-height/2],[0,0,height/2]);for(let i=0;i<sides;i++){const j=(i+1)%sides;triangles.push([2*sides,j,i],[2*sides+1,sides+i,sides+j]);}return{vertices,triangles,object:createMesh({id:'cylinder',plateId:'plate-1',name:'Analytic cylinder',position,positions:triangles.flatMap(t=>t.flatMap(i=>vertices[i]))})};}
